Create `app/lib/db/queries.ts`:
```typescript
import { db } from './client';
import { furiganas } from './schema';
import { eq, and, lt, or, isNull, desc, sql } from 'drizzle-orm';
import type { FuriganaInsert, FuriganaSidebar, PaginationResults, Cursor } from '~/schema/furigana.schema';
import { CursorSchema } from '~/schema/pagination.schema';

export async function insertFurigana(data: FuriganaInsert): Promise<void> {
  await db.insert(furiganas).values(data);
}

export async function getFuriganaById(id: string) {
  const [row] = await db
    .select()
    .from(furiganas)
    .where(and(eq(furiganas.id, id), isNull(furiganas.deletedAt)))
    .limit(1);
  return row ?? null;
}

export async function listFuriganas({
  cursor,
  limit = 20,
}: { cursor?: string; limit?: number }): Promise<PaginationResults<FuriganaSidebar>> {
  const maxLimit = Math.min(limit, 50);

  let decodedCursor: Cursor | null = null;
  if (cursor) {
    try {
      const parsed = JSON.parse(atob(cursor));
      decodedCursor = CursorSchema.parse(parsed);
    } catch {
      throw new Error('Invalid cursor');
    }
  }

  const baseQuery = db
    .select({
      id: furiganas.id,
      rawTextSnippet: sql<string>`SUBSTR(${furiganas.rawText}, 1, 30)`,
      title: furiganas.title,
      createdAt: furiganas.createdAt,
    })
    .from(furiganas)
    .where(isNull(furiganas.deletedAt));

  const query = decodedCursor
    ? baseQuery.where(
        or(
          lt(furiganas.createdAt, decodedCursor.createdAt),
          and(
            eq(furiganas.createdAt, decodedCursor.createdAt),
            lt(furiganas.id, decodedCursor.id)
          )
        )
      )
    : baseQuery;

  const rows = await query
    .orderBy(desc(furiganas.createdAt), desc(furiganas.id))
    .limit(maxLimit + 1);

  const hasMore = rows.length > maxLimit;
  const data = hasMore ? rows.slice(0, maxLimit) : rows;

  const nextCursor = hasMore && data.length > 0
    ? btoa(JSON.stringify({ createdAt: data[data.length - 1].createdAt, id: data[data.length - 1].id }))
    : null;

  const [{ count }] = await db
    .select({ count: sql<number>`COUNT(*)` })
    .from(furiganas)
    .where(isNull(furiganas.deletedAt));

  return {
    data,
    nextCursor,
    total: count,
    hasMore,
  };
}
```

