import { data } from 'react-router';
import type { Route } from './+types/api.furiganas';
import { listFuriganas } from '~/lib/db/queries';
import * as z from 'zod';

const QueryParamsSchema = z.object({
  cursor: z.string().optional(),
  limit: z.coerce.number().int().min(1).max(50).optional().default(20),
});

export async function loader({ request }: Route.LoaderArgs) {
  const url = new URL(request.url);
  const rawParams = Object.fromEntries(url.searchParams);

  const parseResult = QueryParamsSchema.safeParse(rawParams);
  if (!parseResult.success) {
    return data({ error: 'Invalid query parameters' }, { status: 400 });
  }

  const { cursor, limit } = parseResult.data;

  try {
    const results = await listFuriganas({ cursor, limit });
    return data(results, { status: 200 });
  } catch (error) {
    console.error('listFuriganas error:', error);
    return data({ error: 'Failed to fetch entries' }, { status: 500 });
  }
}
