```typescript
import { Link } from 'react-router';
import { useInfiniteQuery } from '@tanstack/react-query';
import {
  Sidebar,
  SidebarHeader,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarMenuSkeleton,
} from '~/components/ui/sidebar';
import { Button } from '~/components/ui/button';
import { fetchFuriganaList } from '~/lib/api/furiganas';

type AppSidebarProps = {
  activeEntryId: string | null;
};

export function AppSidebar({ activeEntryId }: AppSidebarProps) {
  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    isLoading,
    isError,
    refetch,
  } = useInfiniteQuery({
    queryKey: ['furiganas', 'list'],
    queryFn: ({ pageParam }) => fetchFuriganaList(pageParam),
    initialPageParam: undefined as string | undefined,
    getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined,
    staleTime: 30_000,
    refetchOnWindowFocus: true,
  });

  const entries = data?.pages.flatMap((page) => page.data) ?? [];

  return (
    <Sidebar collapsible="offcanvas">
      <SidebarHeader className="border-b p-4">
        <Button asChild variant="default" className="w-full">
          <Link to="/">New</Link>
        </Button>
      </SidebarHeader>

      <SidebarContent>
        <SidebarGroup>
          <SidebarGroupContent>
            <SidebarMenu>
              {isLoading ? (
                Array.from({ length: 5 }).map((_, index) => (
                  <SidebarMenuItem key={index}>
                    <SidebarMenuSkeleton showIcon={false} />
                  </SidebarMenuItem>
                ))
              ) : isError ? (
                <div className="p-4 text-sm text-muted-foreground">
                  Failed to load entries.
                  <button onClick={() => void refetch()} className="ml-2 underline">
                    Retry
                  </button>
                </div>
              ) : entries.length === 0 ? (
                <div className="p-4 text-center text-sm text-muted-foreground">
                  No entries yet.
                </div>
              ) : (
                <>
                  {entries.map((entry) => (
                    <SidebarMenuItem key={entry.id}>
                      <SidebarMenuButton
                        asChild
                        isActive={entry.id === activeEntryId}
                      >
                        <Link to={`/furigana/${entry.id}`}>
                          <div className="flex flex-col gap-1 overflow-hidden">
                            <span className="truncate">
                              {entry.title ?? entry.rawTextSnippet}
                            </span>
                            <span className="text-xs text-muted-foreground">
                              {new Date(entry.createdAt).toLocaleDateString()}
                            </span>
                          </div>
                        </Link>
                      </SidebarMenuButton>
                    </SidebarMenuItem>
                  ))}
                  {hasNextPage && (
                    <SidebarMenuItem>
                      <SidebarMenuButton
                        onClick={() => void fetchNextPage()}
                        disabled={isFetchingNextPage}
                      >
                        {isFetchingNextPage ? 'Loading...' : 'Load more'}
                      </SidebarMenuButton>
                    </SidebarMenuItem>
                  )}
                </>
              )}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter />
    </Sidebar>
  );
}
```

